ROOT=Path.cwd();DOC=ROOT/'map-concepts/reststop-atomic-assets-2026-09-23';G=ROOT/'tmp/image-previews/reststop-trellis-images-2026-09-23';REC=G/'atomic/records'
sys.path.insert(0,str(ROOT/'tmp/ten-run-review-2026-09-22/pythonlib'))
from PIL import Image
catalog=json.loads((DOC/'catalog.json').read_text(encoding='utf8'));assets=[];completed=[];bad=[]
for base in catalog:
 p=REC/(base['id']+'.json');revisions=sorted(REC.glob(base['id']+'-r*.json'));p=revisions[-1] if revisions else p;r={**base,**(json.loads(p.read_text(encoding='utf8')) if p.exists() else {})};r['layout_reference']=base['reference'];file=G/r['file'];r['available']=file.exists() and r.get('status')!='needs_revision'
 if r['available']:
  im=Image.open(file);im.load();r['width'],r['height']=im.size;r['mode']=im.mode;r['sha256']=hashlib.sha256(file.read_bytes()).hexdigest()
  if im.mode=='RGBA':
   a=im.getchannel('A');r['opaque_bbox']=a.point(lambda v:255 if v>204 else 0).getbbox();r['alpha_extrema']=a.getextrema()
   if r['opaque_bbox'] and (r['opaque_bbox'][0]==0 or r['opaque_bbox'][1]==0 or r['opaque_bbox'][2]==im.width or r['opaque_bbox'][3]==im.height):bad.append(r['id'])
  if r.get('status')=='complete':completed.append(r)
 assets.append(r)
