if (G/'audit/index.html').exists():download+='<a href="audit/">Blender 소품 누락 검토 ↗</a>'
page=f'<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>휴게소 · 개별 소품 69종</title><style>{css}</style><main><header><div class="eyebrow">REST STOP / INDIVIDUAL ASSETS</div><h1>한 이미지에, 한 개의 에셋</h1><p>신규 {new_ready}/63종 · 단독 차량 6종 재사용 · 전체 {ready}/69종 완료</p><p>테이블·의자·판매대·진열장·구조 부품을 각각 분리했습니다. 같은 물체는 원본 하나를 복제해서 사용합니다.</p><div class="links">{download}<a href="atomic/asset-map.csv" download>구간별 소품 목록 CSV ↓</a><a href="layout-reference.html">이전 공간 배치 시안 ↗</a></div></header><div class="filters"><label>구간 <select id="zone"><option value="">모든 구간</option>'+''.join(f'<option value="{k}">{k} {v}</option>' for k,v in zone_names.items())+'</select></label><label>분류 <select id="category"><option value="">모든 분류</option>'+''.join(f'<option>{esc(c)}</option>' for c in categories)+'</select></label><label><input id="ready" type="checkbox" checked> 이미지가 있는 항목만</label><span class="count" id="shown"></span></div><div class="grid">'+''.join(cards)+'</div><footer>한 PNG는 독립 물체 또는 연결된 단순 구조 부품 하나입니다. 벽·기둥·가구를 조합한 공간 전체 이미지는 입력 세트에 포함하지 않습니다.<br>이미지 제작·분해 단계입니다. TRELLIS 변환 결과와 게임용 메시·충돌은 아직 검증하지 않았습니다. 나사·부착 손잡이 등은 해당 물체에 포함됩니다.</footer></main><dialog id="viewer"><div class="dialogbar"><strong id="vtitle"></strong><a id="vdownload" download>PNG 저장 ↓</a><button aria-label="닫기" id="close">닫기 ×</button></div><img id="vimage" alt=""></dialog><script>const zone=document.querySelector("#zone"),category=document.querySelector("#category"),ready=document.querySelector("#ready"),all=[...document.querySelectorAll("article")];function filter(){let count=0;all.forEach(a=>{const visible=(!zone.value||a.dataset.zone.split(" ").includes(zone.value))&&(!category.value||a.dataset.category===category.value)&&(!ready.checked||a.dataset.ready==="true");a.hidden=!visible;if(visible)count++});document.querySelector("#shown").textContent="표시 "+count+"종"}zone.onchange=category.onchange=ready.onchange=filter;filter();const d=document.querySelector("#viewer"),im=document.querySelector("#vimage");document.querySelectorAll(".picture").forEach(b=>b.onclick=()=>{im.src=b.dataset.src;im.alt=b.dataset.title;document.querySelector("#vtitle").textContent=b.dataset.title;document.querySelector("#vdownload").href=b.dataset.src;d.showModal()});document.querySelector("#close").onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()};</script></html>'
